        $word = [string]$r.State; $qual = ''; if ($word -match '^(.+?) \((.+)\)$') { $word = $Matches[1]; $qual = $Matches[2] }
        $nh = (& $ui.Rows ([string]$r.Name) $ui.F.Small $lw $h0 2) * $h0 + $v; if ($qual) { $nh = [math]::Max($nh, (2 * $hc + $v)) }
